    for order in Order.objects.select_related('product').iterator():
        product = order.product
        price = product.price if product and product.price is not None else Decimal('0')
        OrderItem.objects.create(
            order=order, product=product, quantity=1, unit_price=price,
            product_name=product.name if product else 'Unknown product',
            seller=(product.source_site or '') if product else '')
        order.total_amount = price
        order.save(update_fields=['total_amount'])


